public partial class MigrationScene {
 async Task CheckpointChecks(){checkpointFixture=true;game.World.Changes.Checkpoint=new();ClearEnemies();Teleport(CheckpointX,ExpeditionCheckpoint.Z+25);player.Position=CheckpointPoint(0,.1f,9);SpawnCheckpoint();MigrationChecks.Assert(infected.Count(e=>IsCheckpointGuard(e.Id))==3,"Three human checkpoint guards stream");MigrationChecks.Assert(checkpointChildren.FindChildren("*","CollisionObject3D",true,false).Count==0,"Sheltered children excluded from combat collision");MigrationChecks.Assert(!game.World.Playable(0,game.World.RiverZ(0)),"Main expansion river remains closed");DrawCheckpoint();await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);
  var barrier=PhysicsRayQueryParameters3D.Create(CheckpointPoint(0,1,7),CheckpointPoint(0,1,5));barrier.Exclude=PursuitExclusions();MigrationChecks.Assert(GetWorld3D().DirectSpaceState.IntersectRay(barrier).Count>0,"Unpaid toll barrier physically blocks crossing");var floor=PhysicsRayQueryParameters3D.Create(CheckpointPoint(0,3,-12),CheckpointPoint(0,-4,-12));floor.Exclude=PursuitExclusions();var hit=GetWorld3D().DirectSpaceState.IntersectRay(floor);MigrationChecks.Assert(hit.Count>0&&Math.Abs(((Vector3)hit["position"]).Y-checkpointFloor)<.15,"Bridge deck matches physical surface");
  game.Life.Food=1;CheckpointAction("pay");MigrationChecks.Assert(!Checkpoint.Paid&&game.Life.Food==1,"Insufficient toll does not consume food");game.Life.Food=8;CheckpointAction("pay");CheckpointAction("pay");MigrationChecks.Assert(Checkpoint.Paid&&game.Life.Food==6&&!Checkpoint.Hostile,"Payment opens party passage once");DrawCheckpoint();await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);MigrationChecks.Assert(GetWorld3D().DirectSpaceState.IntersectRay(barrier).Count==0,"Paid barrier removes physical obstruction");
  player.Position=CheckpointPoint(0,.1f,-15);TickCheckpoint(.1);MigrationChecks.Assert(Checkpoint.Robbery==1,"Crossing triggers robbery behind player");TickCheckpoint(4.1);MigrationChecks.Assert(Checkpoint.Robbery==2,"Robbery plays once and leaves traveller alive");player.Position=CheckpointPoint(0,.1f,16);player.Rotation=Vector3.Zero;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);Checkpoint.DeliveryClock=8.9;Checkpoint.Watch=11.9;MigrationChecks.Assert(CheckpointObserver(player),"Bridge lookout has line of sight to feeding slot");TickCheckpoint(.2);MigrationChecks.Assert(Checkpoint.Revealed&&Checkpoint.DeliveredOnce&&!Checkpoint.Hostile,"Watching reveals food going to sheltered children");player.Position=CheckpointPoint(8,.1f,-5);CheckpointAction("room");CloseMenu();CheckpointAction("donate");CheckpointAction("donate");MigrationChecks.Assert(Checkpoint.Donated&&game.Life.Food==5&&game.Profile.Journal.Seen.Contains("checkpoint/room"),"One optional donation and personal journal");game.Persist();var saved=new ExpeditionGame(game.PathName);MigrationChecks.Assert(saved.World.Changes.Checkpoint.Paid&&saved.World.Changes.Checkpoint.Revealed&&saved.World.Changes.Checkpoint.Robbery==2,"Paid/watch/robbery branches persist");
  game.World.Changes.Checkpoint=new();player.Position=CheckpointPoint(0,.1f,9);DrawCheckpoint();foreach(var g in infected.Where(e=>IsCheckpointGuard(e.Id)))TickCheckpointGuard(g,.01);CheckpointAction("refuse");MigrationChecks.Assert(Checkpoint.Hostile&&!Checkpoint.Paid,"Refusal starts armed combat");var guard=infected.Single(e=>e.Id==CheckpointGuardId(0));game.Shield=0;game.Life.Health=game.MaxHealth;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);double health=game.Life.Health;TickCheckpointGuard(guard,1.1);MigrationChecks.Assert(guard.AttackState=="guard-aim"&&game.Life.Health==health,"Human gun attack has warning wind-up");player.Position=CheckpointPoint(2,.1f,9);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);TickCheckpointGuard(guard,1);MigrationChecks.Assert(game.Life.Health==health,"Captured aim permits dodging");player.Position=CheckpointPoint(0,.1f,9);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);guard.Cooldown=0;TickCheckpointGuard(guard,.01);TickCheckpointGuard(guard,1);MigrationChecks.Assert(game.Life.Health<health,"Guard bullet resolves through physical ray");foreach(var g in infected.Where(e=>IsCheckpointGuard(e.Id)).ToArray())KillEnemy(g);DrawCheckpoint();MigrationChecks.Assert(CheckpointCleared,"Defeated checkpoint guards stay defeated");player.Position=CheckpointPoint(8,.1f,-5);CheckpointAction("room");CloseMenu();MigrationChecks.Assert(Checkpoint.Revealed,"Room can still be understood after combat");game.Life.Health=game.MaxHealth;checkpointFixture=false;ClearEnemies();Teleport(0,12);GD.Print("PASS / checkpoint: three human guards, protected children, deck/barrier collision, payment conservation, one robbery, line-of-sight observation, donation, save, refusal and warning/dodge/physical gunfire");
 }
 async void CaptureCheckpoint(){try{checkpointFixture=true;game.World.Changes.Checkpoint=new();ClearEnemies();game.World.Changes.Time=1050;Teleport(CheckpointX,ExpeditionCheckpoint.Z+25);SpawnCheckpoint();paused=false;weaponRoot.Visible=false;player.Position=CheckpointPoint(0,.1f,17);camera.GlobalPosition=CheckpointPoint(-13,8,28);camera.LookAt(CheckpointPoint(2,1,-2));await ArtShot("checkpoint-01-bridge");
  player.Position=CheckpointPoint(0,.1f,10);camera.Position=new(0,1.65f,0);camera.LookAt(CheckpointPoint(-2,1.2f,5));CheckpointSay("RAE: Two portions of food. Then you cross.");await ArtShot("checkpoint-02-toll");ShowCheckpointPanel(0);await ArtShot("checkpoint-03-choice");CloseMenu();
  Checkpoint.DeliveryClock=8;Checkpoint.DeliveredOnce=true;Checkpoint.Revealed=true;foreach(var e in infected.Where(e=>IsCheckpointGuard(e.Id)))TickCheckpointGuard(e,.01);CheckpointSay("A SMALL VOICE: Is there enough for Lena?\nThe guard's own bowl is empty.");player.Position=CheckpointPoint(3.7f,.1f,-2.8f);camera.Position=new(0,1.65f,0);camera.LookAt(CheckpointPoint(6.7f,1.2f,-6));DrawCheckpoint();await ArtShot("checkpoint-04-locked-room");
  Checkpoint.Hostile=true;var guard=infected.First(e=>e.Id==CheckpointGuardId(0));guard.AttackState="guard-aim";guard.AttackTime=.8;CheckpointPose(guard);player.Position=CheckpointPoint(0,.1f,9);camera.Position=new(0,1.65f,0);camera.LookAt(guard.Body.Position+Vector3.Up*1.4f);CheckpointSay("The guards raise their weapons.");await ArtShot("checkpoint-05-refusal");GetTree().Quit();}catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
 int checkpointCheckAck;
 [Rpc(MultiplayerApi.RpcMode.AnyPeer,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopCheckpointAck(int step){if(coopCheck&&CoopHost&&coopActors.ContainsKey(Multiplayer.GetRemoteSenderId()))checkpointCheckAck=Math.Max(checkpointCheckAck,step);}
 async Task CheckpointCoopChecks(CoopActor actor){checkpointFixture=true;game.World.Changes.Checkpoint=new();ClearEnemies();var home=HostPosition;Teleport(CheckpointX,ExpeditionCheckpoint.Z+25);player.Position=CheckpointPoint(0,.1f,17);actor.Game.Life.Food=6;int hostFood=game.Life.Food;actor.Body.Position=CheckpointPoint(0,.1f,9);RpcId(actor.Id,nameof(CoopPersonal),CoopProfileJson(actor.Game),"",actor.Body.Position,true);CheckpointSync();RpcId(actor.Id,nameof(CoopCheckStage),"checkpoint-pay",actor.Body.Position);await CoopWait(()=>checkpointCheckAck>=1,"Guest checkpoint choice/payment missing",15);if(paused||!Checkpoint.Paid||actor.Game.Life.Food!=4||game.Life.Food!=hostFood)throw new Exception("Checkpoint toll affected wrong player or host UI");
  player.Rotation=new(0,Mathf.Pi,0);actor.Body.Rotation=Vector3.Zero;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);Checkpoint.DeliveryClock=8.9;Checkpoint.Watch=11.9;TickCheckpoint(.2);if(!Checkpoint.Revealed)throw new Exception("Guest observation did not reveal children");actor.Body.Position=CheckpointPoint(0,.1f,-15);RpcId(actor.Id,nameof(CoopPersonal),CoopProfileJson(actor.Game),"",actor.Body.Position,true);TickCheckpoint(.1);TickCheckpoint(4.1);if(Checkpoint.Robbery!=2)throw new Exception("Guest crossing did not trigger robbery");actor.Body.Position=CheckpointPoint(8,.1f,-5);RpcId(actor.Id,nameof(CoopPersonal),CoopProfileJson(actor.Game),"",actor.Body.Position,true);CheckpointSync();RpcId(actor.Id,nameof(CoopCheckStage),"checkpoint-room",actor.Body.Position);await CoopWait(()=>checkpointCheckAck>=2,"Guest checkpoint room/donation missing",15);if(paused||actor.Game.Life.Food!=3||game.Life.Food!=hostFood||!actor.Game.Profile.Journal.Seen.Contains("checkpoint/room"))throw new Exception("Donation or journal isolation failed");checkpointFixture=false;ClearEnemies();Teleport(home.X,home.Z);actor.Body.Position=HostPosition+Vector3.Right*3;RpcId(actor.Id,nameof(CoopPersonal),CoopProfileJson(actor.Game),"",actor.Body.Position,true);GD.Print("PASS / two-process checkpoint: guest dialogue/payment isolation, shared barrier, guest observation/crossing, robbery, protected-room journal and donation");}
 async Task ClientCheckpointChecks(string stage,Vector3 target){checkpointFixture=true;await CoopWait(()=>Distance(player.Position,target)<1,"Checkpoint test teleport missing",15);SpawnCheckpoint();if(stage=="checkpoint-pay"){await CoopWait(()=>infected.Count(e=>IsCheckpointGuard(e.Id))==3,"Guard replicas missing");CoopRequest("checkpoint","open");await CoopWait(()=>paused,"Checkpoint guest dialogue missing");CheckpointChoice("pay");await CoopWait(()=>Checkpoint.Paid&&game.Life.Food==4&&!paused,"Guest toll result missing");CoopRequest("checkpoint","pay");await CoopDelay(.2);if(game.Life.Food!=4)throw new Exception("Duplicate toll charged guest twice");RpcId(1,nameof(CoopCheckpointAck),1);}else{await CoopWait(()=>Checkpoint.Revealed&&Checkpoint.Robbery==2,"Checkpoint reveal/robbery state missing");CoopRequest("checkpoint","room");await CoopWait(()=>paused&&game.Profile.Journal.Seen.Contains("checkpoint/room"),"Guest room journal/UI missing");CheckpointChoice("donate");await CoopWait(()=>Checkpoint.Donated&&game.Life.Food==3,"Guest food donation missing");RpcId(1,nameof(CoopCheckpointAck),2);checkpointFixture=false;}}
}
